  IF (SELECT COUNT(*) FROM app_user) <> 100
     OR (SELECT COUNT(*) FROM restaurant) <> 50
     OR (SELECT COUNT(*) FROM dish) <> 250
     OR (SELECT COUNT(*) FROM review) <> 1000
     OR EXISTS (SELECT 1 FROM restaurant_rating_summary WHERE review_count = 0)
  THEN RAISE EXCEPTION 'Generated seed failed its data checks';
  END IF;
END $$;

